                delta[name] = null;
            }
        }
        foreach (KeyValuePair<string, string> header in after)
        {
            if (!before.TryGetValue(header.Key, out string? old) || old != header.Value)
            {
                delta[header.Key] = header.Value;
            }
        }
        return delta;
    }

    /// <summary>
    /// Reapplies the edits a call hook made. A header named in
    /// <paramref name="skip"/> was just set again by authentication, and that
    /// fresh value wins.
    /// </summary>
    private static void ApplyHookDelta(
        Dictionary<string, string> built,
        Dictionary<string, string?> delta,
        HashSet<string>? skip
    )
    {
        foreach (KeyValuePair<string, string?> edit in delta)
        {
            if (skip is not null && skip.Contains(edit.Key))
            {
                continue;
            }
            foreach (string existing in built.Keys.ToList())
            {
                if (string.Equals(existing, edit.Key, StringComparison.OrdinalIgnoreCase))
                {
                    _ = built.Remove(existing);
                }
            }
            if (edit.Value is not null)
            {
                built[edit.Key] = edit.Value;
            }
        }
    }

    /// <summary>
    /// Sends one request through the transport. A transport failure is raised without the
    /// request it came from, so the method and path that failed are recorded on it here.
    /// </summary>
    private static async Task<ApiHttpResponse> SendRecordingRequestAsync(
        IApiClient apiClient,
        string method,
        Uri requestUri,
        Dictionary<string, string> headers,
        object? requestBody,
        Func<Task<Dictionary<string, string>>> refreshHeaders,
        int? timeout,
        int? maxRetries,
        CancellationToken cancellationToken
    )
    {
        try
        {
            return await apiClient
                .SendRequestAsync(
                    method,
                    requestUri,
                    headers,
                    requestBody,
                    false,
                    refreshHeaders,
                    timeout,
                    maxRetries,
                    cancellationToken
                )
                .ConfigureAwait(false);
        }
        catch (NetworkException ex)
        {
            ex.RecordRequest(method, requestUri.AbsolutePath);
            throw;
        }
    }

    /// <summary>
    /// Rejects a missing required option with the canonical message. A helper
    /// rather than an inline null test, so a null Options object is reported
    /// through its first required field instead of as a bare null argument.
    /// </summary>
    /// <param name="value">The option value, null when it or its Options object is missing.</param>
    /// <param name="paramName">The dotted option path reported as the argument name.</param>
    /// <param name="message">The canonical missing-parameter message.</param>
    /// <exception cref="ArgumentNullException">Thrown when <paramref name="value"/> is null.</exception>
    protected static void RequireOption(
        [System.Diagnostics.CodeAnalysis.NotNull] object? value,
        string paramName,
        string message
    )
    {
        if (value is null)
        {
            throw new ArgumentNullException(paramName, message);
        }
    }

    /// <summary>
    /// Serializes a parameter declared with <c>content: application/json</c>
    /// through the SDK's own object serializer, then encodes the resulting JSON
    /// text once by the parameter's location: a path segment is
    /// percent-encoded, a header is sent verbatim after a CR/LF check, and a
    /// cookie value is percent-encoded. A serialization failure is a
    /// <see cref="SerializationException"/>, never a dropped or empty value.
    /// </summary>
    /// <param name="value">The parameter value.</param>
    /// <param name="location">One of <c>path</c>, <c>header</c> or <c>cookie</c>.</param>
    /// <returns>The encoded parameter text.</returns>
    protected string SerializeContentParameter(object value, string location)
    {
        string json = Serializer.Serialize(value);
        switch (location)
        {
            case "path":
                return ValueSerializer.EncodePathSegment(json);
            case "cookie":
                return Uri.EscapeDataString(json).Replace(".", "%2E", StringComparison.Ordinal);
            default:
                if (
                    json.Contains('\r', StringComparison.Ordinal)
                    || json.Contains('\n', StringComparison.Ordinal)
                )
                {
                    throw new ArgumentException("Header value contains a CR or LF character");
                }
                return json;
        }
    }

    /// <summary>
    /// Invoke an API operation.
    /// </summary>
    protected async Task<T?> InvokeApiAsync<T>(
        string method,
        string path,
        Dictionary<string, object?> queryParams,
        Dictionary<string, string> headerParams,
        object? body,
        string[] accepts,
        string contentType,
        Type? returnType,
        IAuthenticator? auth = null
    )
    {
        ApiResult<T> result = await InvokeApiForResultAsync<T>(
                method,
                path,
                queryParams,
                headerParams,
                body,
                accepts,
                contentType,
                returnType,
                auth
            )
            .ConfigureAwait(false);
        return result.Data;
    }

    /// <summary>
    /// Mirrors <see cref="DefaultApiClient"/>'s text/binary classification so the
    /// response body can be decoded the same way it was encoded: text-like content
    /// types are stored as a decoded string, everything else as base64. The full
    /// Content-Type header (including any charset/parameters) is tolerated by
    /// matching on the leading media type.
    /// </summary>
    private static bool IsTextResponseContentType(string? contentType)
    {
        if (string.IsNullOrEmpty(contentType))
        {
            return true;
        }
        string mediaType = contentType.Split(';')[0].Trim();
        return mediaType.Length == 0
            || mediaType.StartsWith("text/", StringComparison.OrdinalIgnoreCase)
            || mediaType.Equals("application/json", StringComparison.OrdinalIgnoreCase)
            || mediaType.Equals("application/xml", StringComparison.OrdinalIgnoreCase)
            || mediaType.Equals("application/javascript", StringComparison.OrdinalIgnoreCase)
            || mediaType.EndsWith("+json", StringComparison.OrdinalIgnoreCase)
            || mediaType.EndsWith("+xml", StringComparison.OrdinalIgnoreCase);
    }

    /// <summary>
    /// Flattens a model into its top-level wire fields for a deepObject query
    /// parameter: the model is serialized with the SDK serializer and each
    /// JSON property becomes one entry (strings unquoted, other values as their
    /// JSON text). Null properties are omitted by the serializer.
    /// </summary>
    /// <param name="value">The model to flatten.</param>
    /// <returns>The wire field names mapped to their values.</returns>
    protected IDictionary<string, object?> ToDeepObjectFields(object value)
    {
        ArgumentNullException.ThrowIfNull(value);
        Dictionary<string, object?> fields = [];
        using System.Text.Json.JsonDocument document = System.Text.Json.JsonDocument.Parse(
            Serializer.Serialize(value)
        );
        if (document.RootElement.ValueKind != System.Text.Json.JsonValueKind.Object)
        {
            return fields;
        }
        foreach (System.Text.Json.JsonProperty property in document.RootElement.EnumerateObject())
        {
            fields[property.Name] =
                property.Value.ValueKind == System.Text.Json.JsonValueKind.String
                    ? property.Value.GetString()
                    : property.Value.GetRawText();
        }
        return fields;
    }

    /// <summary>
    /// Builds the error raised when an <c>application/x-www-form-urlencoded</c>
    /// field holds a model, map or array of objects: the generator emits no
    /// OAS encoding style for such values, so no wire form is defined and the
    /// SDK refuses rather than sending the value's ToString().
    /// </summary>
    private static SerializationException NonScalarFormField(string name)
    {
        return new SerializationException(
            "form-urlencoded field " + name + " must be a scalar or array of scalars"
        );
    }

    /// <summary>
    /// Decodes the transport's base64 carrier of a binary body to text; a body that is not
    /// valid base64 (a custom client that returns the text itself) comes back unchanged.
    /// </summary>
    private static string DecodeBinaryText(string body)
    {
        try
        {
            return System.Text.Encoding.UTF8.GetString(Convert.FromBase64String(body));
        }
        catch (FormatException)
        {
            return body;
        }
    }

    /// <summary>
    /// Recovers the raw bytes of a binary response body. When <paramref name="base64Expected"/>
    /// is true the body is decoded from base64 (how <see cref="DefaultApiClient"/> encodes
    /// non-text payloads); if that fails, or when base64 is not expected, the literal
    /// UTF-8 bytes of the body are returned so that custom transports returning raw text
    /// still produce a usable stream.
    /// </summary>
    private static byte[] DecodeBinaryBody(string body, bool base64Expected)
    {
        if (base64Expected)
        {
            try
            {
                return Convert.FromBase64String(body);
            }
            catch (FormatException)
            {
                /* not base64 — fall through to literal UTF-8 bytes */
            }
        }
        return System.Text.Encoding.UTF8.GetBytes(body);
    }

    /// <summary>
    /// Encodes a value for an <c>application/x-www-form-urlencoded</c> request
    /// body. Per the WHATWG URL / HTML form-encoding standard (which defines
    /// the media type) a space is encoded as <c>+</c>, not <c>%20</c>. Every
    /// other reserved character is percent-encoded. This matches the 9-SDK
    /// majority (Java/Go/Python/Ruby/Kotlin/Dart/Elixir/Node/Rust) so the wire
    /// bytes of a form body are identical across languages.
    /// </summary>
    private static string FormUrlEncode(string value)
    {
        return Uri.EscapeDataString(value).Replace("%20", "+", StringComparison.Ordinal);
    }

    /// <summary>
    /// Extract the single binary payload from a form-style body Dictionary when
    /// a raw-binary content-type (application/octet-stream or image/*) was
    /// selected for an operation that also declares multipart/form-data.
    /// </summary>
    /// <remarks>
    /// The API layer always builds a form Dictionary keyed by the operation's
    /// declared parts. For a raw-binary upload only the binary part travels on
    /// the wire — the auxiliary string parts (classification, notes, ...) belong
    /// to the multipart variant and are dropped. This returns the first
    /// binary-typed value (<see cref="System.IO.Stream"/> or <c>byte[]</c>) so
    /// the transport sends its raw bytes under the selected Content-Type rather
    /// than a multipart envelope.
    /// </remarks>
    /// <param name="formBody">The form-style body Dictionary.</param>
    /// <returns>The binary part suitable for raw transmission.</returns>
    /// <exception cref="ApiException">Thrown when no binary part is present.</exception>
    private static object ExtractBinaryPart(Dictionary<string, object> formBody)
    {
        foreach (object value in formBody.Values)
        {
            if (value is System.IO.Stream || value is byte[])
            {
                return value;
            }
        }
        throw new ArgumentException(
            "No binary payload found in request body for raw octet-stream upload",
            nameof(formBody)
        );
    }

    private static string BuildQueryString(Dictionary<string, object?> queryParams)
    {
        List<string> parts = [];
        foreach (KeyValuePair<string, object?> entry in queryParams)
        {
            object? value = entry.Value;
            /* OAS allowReserved: a wrapped value keeps RFC 3986 reserved
             * characters literal instead of percent-encoding them. */
            bool allowReserved = false;
            if (value is ValueSerializer.AllowReservedValue reserved)
            {
                value = reserved.Value;
                allowReserved = true;
            }
            if (value is ValueSerializer.ExplodedFields exploded)
            {
                foreach (KeyValuePair<string, string> field in exploded.Fields)
                {
                    parts.Add(
                        Uri.EscapeDataString(field.Key)
                            + "="
                            + EncodeQueryValue(field.Value, allowReserved)
                    );
                }
            }
            else if (value != null)
            {
                if (value is System.Collections.IEnumerable enumerable and not string)
                {
                    foreach (object? item in enumerable)
                    {
                        parts.Add(
                            Uri.EscapeDataString(entry.Key)
                                + "="
                                + EncodeQueryValue(item?.ToString() ?? "", allowReserved)
                        );
                    }
                }
                else
                {
                    string str = value is bool b ? (b ? "true" : "false") : value.ToString()!;
                    parts.Add(
                        Uri.EscapeDataString(entry.Key) + "=" + EncodeQueryValue(str, allowReserved)
                    );
                }
            }
        }
        return string.Join("&", parts);
    }

    /// <summary>
    /// Encodes a query-parameter value, preserving RFC 3986 reserved characters
    /// when the parameter declared <c>allowReserved: true</c>.
    /// </summary>
    private static string EncodeQueryValue(string value, bool allowReserved)
    {
        return allowReserved
            ? ValueSerializer.EncodeQueryAllowingReserved(value)
            : Uri.EscapeDataString(value);
    }

    /// <summary>
    /// Sets a request header. Header names are case-insensitive (RFC 9110
    /// section 5.1), so any existing header of the same name in another case is
    /// replaced rather than sent beside the new one.
    /// </summary>
    private static void SetHeaderIgnoringCase(
        Dictionary<string, string> headers,
        string name,
        string value
    )
    {
        foreach (string existing in headers.Keys.ToList())
        {
            if (string.Equals(existing, name, StringComparison.OrdinalIgnoreCase))
            {
                _ = headers.Remove(existing);
            }
        }
        headers[name] = value;
    }

    /// <summary>RFC 6265 cookie-name validation (RFC 7230 token).</summary>
    /// <remarks>
    /// Exposed to derived API classes so operation-level cookie parameters
    /// (in: cookie) are validated with the identical rules as auth-provided
    /// cookies, keeping the Cookie header free of header-injection vectors.
    /// </remarks>
    protected static bool IsValidCookieName(string name)
    {
        if (string.IsNullOrEmpty(name))
        {
            return false;
        }
        foreach (char c in name)
        {
            bool ok =
                c is >= 'A' and <= 'Z' or >= 'a' and <= 'z' or >= '0' and <= '9'
                || "!#$%&'*+-.^_`|~".Contains(c, StringComparison.Ordinal);
            if (!ok)
            {
                return false;
            }
        }
        return true;
    }

    /// <summary>RFC 6265 cookie-value validation (cookie-octet*).</summary>
    /// <remarks>
    /// Exposed to derived API classes so operation-level cookie parameters
    /// (in: cookie) are validated with the identical rules as auth-provided
    /// cookies, rejecting CR/LF and control characters that would otherwise
    /// allow header injection into the Cookie request header.
    /// </remarks>
    protected static bool IsValidCookieValue(string value)
    {
        if (value == null)
        {
            return false;
        }
        foreach (char c in value)
        {
            bool ok =
                c
                is (char)0x21
                    or >= (char)0x23
                    and <= (char)0x2B
                    or >= (char)0x2D
                    and <= (char)0x3A
                    or >= (char)0x3C
                    and <= (char)0x5B
                    or >= (char)0x5D
                    and <= (char)0x7E;
            if (!ok)
            {
                return false;
            }
        }
        return true;
    }
}
